import { createApi, fetchBaseQuery } from '@reduxjs/toolkit/query/react';

export const api = createApi({
  // The base query function that handles the actual HTTP requests
  baseQuery: fetchBaseQuery({ baseUrl: '/api' }),
  // Tag types define the categories of data for cache invalidation
  tagTypes: ['User', 'Post', 'Comment'],
  endpoints: (builder) => ({
    // Query endpoint - fetches data (GET by default)
    getUsers: builder.query({
      query: () => '/users',
      providesTags: ['User']
    }),

    getUserById: builder.query({
      query: (id) => `/users/${id}`,
      providesTags: (result, error, id) => [{ type: 'User', id }]
    }),

    // Mutation endpoint - modifies data (POST by default)
    createUser: builder.mutation({
      query: (body) => ({
        url: '/users',
        method: 'POST',
        body
      }),
      invalidatesTags: ['User']
    }),

    updateUser: builder.mutation({
      query: ({ id, ...body }) => ({
        url: `/users/${id}`,
        method: 'PATCH',
        body
      }),
      invalidatesTags: (result, error, { id }) => [{ type: 'User', id }]
    })
  })
});

