import { useGetUsersQuery, useCreateUserMutation } from './api';

function UserList() {
  const {
    data: users,
    isLoading,
    isFetching,
    isError,
    error,
    refetch
  } = useGetUsersQuery();

  const [createUser, { isLoading: isCreating }] = useCreateUserMutation();

  const handleAddUser = async (userData) => {
    try {
      await createUser(userData).unwrap();
    } catch (err) {
      console.error('Failed to create user:', err);
    }
  };

  if (isLoading) return <div>Loading users...</div>;
  if (isError) return <div>Error: {error.message}</div>;

  return (
    <div>
      <button onClick={() => refetch()}>Refresh</button>
      <ul>
        {users?.map(user => (
          <li key={user.id}>{user.name}</li>
        ))}
      </ul>
    </div>
  );
}

export const api = createApi({
  reducerPath: 'api',
  baseQuery: fetchBaseQuery({ baseUrl: '/api' }),
  tagTypes: ['Post'],
  endpoints: (builder) => ({
    getPosts: builder.query({
      query: () => '/posts',
      // How long to keep data in cache (seconds)
      keepUnusedDataFor: 300, // 5 minutes
      // Force refetch on window focus
      refetchOnFocus: true,
      // Force refetch when coming back online
      refetchOnReconnect: true
    }),

    getTrendingPosts: builder.query({
      query: () => '/posts/trending',
      // Very short cache for frequently changing data
      keepUnusedDataFor: 30
    })
  })
});
